// Where each greeting's language comes from: its family, a short story and, where linguists
// commonly cite one, a rough breakdown of where its vocabulary comes from.
export const LANGS = {"Catalan":{"family":"Indo-European › Italic › Romance","about":"Grew from the Vulgar Latin of Roman northeastern Iberia, shaped by Frankish rule in the Marca Hispanica and by the medieval Crown of Aragon's trade empire across the Mediterranean. Written in Latin script with the distinctive 'l·l'. Fun fact: it is the only official language of Andorra."},
"Arabic":{"family":"Afro-Asiatic › Semitic › Central Semitic","about":"Descends from Old Arabic of the Arabian Peninsula. The Quran fixed its classical form, and Islam carried it from Spain to Iraq. Written right to left in the Arabic script, which grew out of Nabataean Aramaic writing. Fun fact: English 'algebra', 'coffee', 'sugar' and 'zero' all trace back to Arabic."},
"Dari":{"family":"Indo-European › Indo-Iranian › Iranian › Western Iranian","about":"Dari is the Afghan form of Persian, descended from Middle Persian; its name likely comes from 'dar', the royal court. Islam brought Arabic words, and Turkic and Pashto neighbours added more. Written in Perso-Arabic script. Fun fact: it keeps older vowels like 'ē' and 'ō' that Iranian Persian merged away."},
"English":{"family":"Indo-European › Germanic › West Germanic","about":"Grew from the dialects of the Angles, Saxons and Jutes who settled Britain in the 5th century. Vikings added everyday words like 'sky' and 'egg', and the Norman Conquest of 1066 flooded it with French. Latin script. Fun fact: even 'they', 'them' and 'their' were borrowed from Old Norse.","mix":[["French",30],["Latin",30],["Germanic (Old English, Norse, Dutch)",25],["Greek",5],["Other",10]]},
"Albanian":{"family":"Indo-European › Albanian","about":"Forms its own branch of Indo-European, descended from an ancient Balkan language, possibly Illyrian. Centuries of Latin contact, then Greek, Slavic, Turkish and Italian, enriched its vocabulary. Written in Latin script since a standard alphabet was agreed in 1908. Fun fact: Albanians call their language 'shqip'."},
"Armenian":{"family":"Indo-European › Armenian","about":"Its own branch of Indo-European. In 405 AD the monk Mesrop Mashtots invented its unique alphabet to translate the Bible. Long contact with Parthian Persia left so many Iranian words that scholars once thought it was an Iranian language. Fun fact: the alphabet's letters also served as numbers."},
"Portuguese":{"family":"Indo-European › Italic › Romance","about":"Grew from Vulgar Latin in Gallaecia, Iberia's Roman northwest, alongside Galician. Germanic Suebi and Visigoths left a few words, and Moorish rule left hundreds of Arabic ones like 'azeite' (olive oil). Latin script. Fun fact: sailors spread it to Brazil, Africa and Asia, and it gave Japanese 'pan' (bread)."},
"Spanish":{"family":"Indo-European › Italic › Romance","about":"Grew from the Vulgar Latin of Castile in northern Iberia. Visigoths added Germanic words, and nearly 800 years of Moorish rule left thousands of Arabic ones. Latin script, with its famous ñ. Fun fact: over 4,000 Spanish words come from Arabic, like 'ojalá' from 'law šā' Allāh'.","mix":[["Latin",75],["Arabic",10],["Greek",5],["Other",10]]},
"German":{"family":"Indo-European › Germanic › West Germanic","about":"Developed from the dialects of Germanic tribes in central Europe; the High German consonant shift set it apart from Dutch and English. Latin came via the Church, French via courtly culture, and Luther's Bible helped unify the written standard. Latin script with ä, ö, ü and ß. Fun fact: every noun is capitalised."},
"Azerbaijani":{"family":"Turkic › Oghuz","about":"Brought to the Caucasus and northwest Iran by Oghuz Turkic tribes from the 11th century under the Seljuks. Centuries alongside Persian, plus Arabic via Islam and Russian under Tsarist and Soviet rule, shaped its vocabulary. Latin script in Azerbaijan, Perso-Arabic in Iran. Fun fact: it is very close to Turkish."},
"Bosnian":{"family":"Indo-European › Slavic › South Slavic","about":"A standard form of the South Slavic language it shares with Serbian, Croatian and Montenegrin, descended from Common Slavic. Four centuries of Ottoman rule left many Turkish, Arabic and Persian words, like 'avlija' (courtyard). Latin and Cyrillic scripts. Fun fact: medieval Bosnia used its own Cyrillic variant, Bosančica."},
"Bengali":{"family":"Indo-European › Indo-Iranian › Indo-Aryan › Eastern","about":"Grew from Magadhi Prakrit, a spoken cousin of Sanskrit, around 1000 AD. Persian came with the Bengal Sultanate and Mughals, then Portuguese and English with trade and British rule. Written in the Bengali-Assamese script. Fun fact: UNESCO's International Mother Language Day, 21 February, honours Bengali language martyrs of 1952."},
"Dutch":{"family":"Indo-European › Germanic › West Germanic","about":"Grew from Old Low Franconian, the speech of the Franks who stayed in the Low Countries. French and Latin, and later English, added words, while Dutch seafaring spread its own terms worldwide. Latin script, with the 'ij' digraph. Fun fact: English 'yacht', 'cookie' and 'boss' all come from Dutch."},
"French":{"family":"Indo-European › Italic › Romance","about":"Grew from the Vulgar Latin of Roman Gaul, with a few Celtic Gaulish remnants, then reshaped by the Germanic Franks, who gave it its name and hundreds of words. Latin script with accents. Fun fact: the Académie française has guarded the language since 1635, and roughly a third of English vocabulary came via French."},
"Bulgarian":{"family":"Indo-European › Slavic › South Slavic","about":"Descends from the Slavic speech that settled the Balkans; Old Church Slavonic, the first Slavic literary language, is its ancestor. The Turkic Bulgars gave it their name, and Ottoman rule added Turkish words. Written in Cyrillic, born in the First Bulgarian Empire. Fun fact: it dropped noun cases and puts 'the' on the end of words."},
"Kirundi":{"family":"Niger-Congo › Atlantic-Congo › Bantu","about":"A Bantu language of Burundi, so close to Kinyarwanda that speakers understand each other. It spread with Bantu migrations; German and then Belgian colonial rule left French loans, and Swahili adds trade words. Latin script. Fun fact: it is tonal, so changing the pitch of a syllable can change a word's meaning."},
"Malay":{"family":"Austronesian › Malayo-Polynesian › Malayic","about":"Grew from Old Malay of Sumatra, the trade language of the Srivijaya empire. Sanskrit came with Hindu-Buddhist kingdoms, Arabic and Persian with Islam, then Portuguese, Dutch and English through colonial trade. Written in Latin script (Rumi) and Arabic-based Jawi. Fun fact: English 'amok' and 'orangutan' ('person of the forest') come from Malay."},
"Dzongkha":{"family":"Sino-Tibetan › Tibeto-Burman › Tibetic","about":"Descends from Old Tibetan and is Bhutan's national language; its name means 'language of the fortress' (dzong). Buddhism brought Classical Tibetan, still used in Bhutan's monasteries, and English is common in schools. Written in Tibetan script. Fun fact: it became Bhutan's national language only in 1971."},
"Belarusian":{"family":"Indo-European › Slavic › East Slavic","about":"Descends from Old East Slavic and grew up within the Grand Duchy of Lithuania, where its ancestor, Ruthenian, was a language of state. Polish contact left many words, and Russian more recently. Cyrillic script. Fun fact: it is the only Slavic language using the letter 'ў', a short 'u' sound."},
"Lingala":{"family":"Niger-Congo › Atlantic-Congo › Bantu","about":"Grew in the 19th century from Bobangi, a trade language along the Congo River, and spread through the colonial army, the city of Kinshasa and its famous music. It borrows heavily from French, with some Portuguese and English. Latin script. Fun fact: Congolese rumba and soukous carried Lingala songs across Africa."},
"Sango":{"family":"Ngbandi-based creole","about":"Grew from Ngbandi, a language of the Ubangi River, which traders, boatmen and colonial soldiers simplified into a lingua franca; many now learn it from birth. Everyday words are mostly Ngbandi, while modern and technical ones come from French. Latin script. Fun fact: nearly everyone in the Central African Republic speaks it."},
"Swiss German":{"family":"Indo-European › Germanic › West Germanic › Alemannic","about":"A group of Alemannic dialects descended from the Alamanni, who settled the region from the 5th century. They kept older sounds, like 'Huus' for 'Haus', and borrowed French words like 'merci' and 'Velo' (bike). Mostly spoken; writing uses Standard German in Latin script. Fun fact: the cosy '-li' ending gave us 'Müesli'."},
"Mandarin Chinese":{"family":"Sino-Tibetan › Sinitic","about":"Descends from Old and Middle Chinese; Mandarin grew from northern dialects, and the Beijing speech of imperial officials became the standard. Buddhism brought Sanskrit-derived words, and Japanese supplied many modern terms. Written in Chinese characters, simplified in mainland China. Fun fact: its four tones turn 'ma' into mother, hemp, horse or scold."},
"Greek":{"family":"Indo-European › Hellenic","about":"Its own branch of Indo-European, recorded for over 3,400 years, from Mycenaean Linear B to today. Koine Greek spread with Alexander and the New Testament; Byzantine, Venetian and Ottoman eras added Latin, Italian and Turkish words. Greek alphabet, adapted from Phoenician. Fun fact: 'alphabet' itself comes from Greek alpha and beta."},
"Czech":{"family":"Indo-European › Slavic › West Slavic","about":"Descends from the West Slavic speech of Bohemia and Moravia. Long Habsburg rule brought German loans, and 19th-century revivalists coined native words to replace them. Latin script with háčeks, an idea credited to Jan Hus. Fun fact: 'robot' comes from Czech 'robota' (forced labour), and 'strč prst skrz krk' has no vowels."},
"Danish":{"family":"Indo-European › Germanic › North Germanic","about":"Descends from the eastern dialect of Old Norse, carried by Vikings as far as England and Normandy. Low German from Hanseatic merchants added many words, then French and English. Latin script with æ, ø and å. Fun fact: Danish kings once ruled England, which is partly why English has Norse words like 'egg' and 'knife'."},
"Estonian":{"family":"Uralic › Finnic","about":"A Finnic language of the Uralic family, a close cousin of Finnish. Centuries under Danish, Swedish, Russian and especially Baltic German lords left many German loans. Latin script with õ. Fun fact: in the early 1900s Johannes Aavik invented new words from scratch, and some, like 'roim' (crime), are still used today."},
"Tigrinya":{"family":"Afro-Asiatic › Semitic › Ethiopian Semitic","about":"An Ethiopian Semitic language of Eritrea and Tigray, closely related to Ge'ez, the ancient language of Aksum still used in church. Cushitic neighbours shaped it, and Eritrea's Italian colonial era left loans like 'makina' (car). Written in Ge'ez (Ethiopic) script. Fun fact: each letter stands for a whole syllable."},
"Amharic":{"family":"Afro-Asiatic › Semitic › Ethiopian Semitic","about":"An Ethiopian Semitic language whose ancestors mixed with Cushitic neighbours like Agaw, borrowing sounds and grammar. It became the royal court language from the 13th century. Written in the Ge'ez script (fidel), with over 200 syllable characters. Fun fact: it is the second most widely spoken Semitic language after Arabic."},
"Finnish":{"family":"Uralic › Finnic","about":"A Finnic language whose ancestors reached the Baltic region thousands of years ago. Early Baltic and Germanic neighbours lent basic words like 'kuningas' (king), and 600 years of Swedish rule added more. Latin script; Mikael Agricola wrote its first books in the 1540s. Fun fact: it has no gender, using 'hän' for both he and she."},
"Fijian":{"family":"Austronesian › Oceanic › Central Pacific","about":"An Oceanic language descended from the speech of Lapita seafarers who settled Fiji about 3,000 years ago, with close ties to Polynesian. Missionaries wrote it down; English and Fiji Hindi add loans. Latin script where 'c' sounds like 'th' and 'b' like 'mb'. Fun fact: 'bula' means both hello and life."},
"Pohnpeian":{"family":"Austronesian › Oceanic › Micronesian","about":"A Micronesian language of Pohnpei in the Federated States of Micronesia, descended from the speech of Oceanic voyagers. Spanish, German, Japanese and American rule each left loanwords. Latin script, introduced by missionaries. Fun fact: it has a special honorific register of respectful words used when speaking to or about chiefs."},
"Georgian":{"family":"Kartvelian › Karto-Zan","about":"A Kartvelian language, from a small family native to the Caucasus with no proven outside relatives. Persian, Arabic, Greek, Turkish and Russian contact added loans. Written in its own 33-letter Mkhedruli alphabet. Fun fact: it allows huge consonant clusters, as in 'gvprtskvni' (you peel us)."},
"Twi":{"family":"Niger-Congo › Kwa › Akan","about":"A dialect group of Akan, the Kwa language of the Asante and Akuapem peoples of Ghana. Trade with Portuguese, Dutch and British merchants on the Gold Coast left loans like 'krataa' (paper, from Portuguese 'carta'). Latin script with ɛ and ɔ. Fun fact: Ghanaian day names like Kofi (born on Friday) come from Akan."},
"Wolof":{"family":"Niger-Congo › Atlantic › Senegambian","about":"An Atlantic language of Senegal and Gambia. Islam brought Arabic words, and for centuries it was written in the Arabic-based Wolofal script; French colonial rule added many more loans. Now mostly Latin script. Fun fact: Dakar's urban Wolof mixes in French freely, and Senegal's mbalax music is sung in Wolof."},
"Croatian":{"family":"Indo-European › Slavic › South Slavic","about":"A standard form of the South Slavic language it shares with Serbian, Bosnian and Montenegrin, descended from Common Slavic. Venice gave coastal dialects Italian words, while Vienna and Budapest added German and Hungarian. Latin script, though medieval Croats used Glagolitic. Fun fact: 'cravat' comes from 'Hrvat' (Croat)."},
"Haitian Creole":{"family":"French-based creole","about":"Born in 17th and 18th century Saint-Domingue among enslaved Africans speaking Fon, Ewe, Kikongo and more, who forged a new language from French. Most words are French, while its grammar shows West African influence. Latin script with phonetic spelling. Fun fact: nearly all Haitians speak it, while far fewer are fluent in French.","mix":[["French",90],["African languages & other",10]]},
"Hungarian":{"family":"Uralic › Ugric","about":"A Ugric language brought by Magyar tribes who migrated from the Urals region and settled the Carpathian Basin around 895. Turkic, Slavic, Latin and German neighbours all added loans. Latin script; an old runic script, rovásírás, survives. Fun fact: its closest relatives, Khanty and Mansi, are spoken in western Siberia."},
"Indonesian":{"family":"Austronesian › Malayo-Polynesian › Malayic","about":"A standard form of Malay, the old trade language of the archipelago, chosen in 1928 as the national language to unite hundreds of ethnic groups. Sanskrit, Arabic, Portuguese, Dutch, Javanese and English all left words. Latin script. Fun fact: Portuguese gave it 'sepatu' (shoe) and 'meja' (table)."},
"Irish":{"family":"Indo-European › Celtic › Goidelic","about":"A Goidelic Celtic language, first recorded in Ogham inscriptions from around the 4th century. Christianity brought Latin, and Norse, Norman French and English followed. Latin script, once in a distinctive Gaelic type. Fun fact: English 'whiskey' comes from Irish 'uisce beatha', meaning 'water of life'."},
"Hebrew":{"family":"Afro-Asiatic › Semitic › Northwest Semitic","about":"A Canaanite language of ancient Israel and the Bible, it lived on for centuries in prayer and scholarship and was revived as an everyday tongue from the 1880s, led by Eliezer Ben-Yehuda. Aramaic, Yiddish and European languages shaped modern Hebrew. Written right to left in Hebrew script. Fun fact: it is the most successful language revival ever."},
"Hindi":{"family":"Indo-European › Indo-Iranian › Indo-Aryan › Central","about":"Grew from Shauraseni Prakrit and the Khari Boli dialect around Delhi. Persian and Arabic arrived with the Delhi Sultanate and Mughals, and English with British rule. Written in Devanagari. Fun fact: everyday Hindi and Urdu are largely mutually intelligible, and English 'shampoo' and 'bungalow' come from Hindi.","mix":[["Sanskrit (tatsama + tadbhava)",55],["Persian & Arabic",25],["Native/other",15],["English",5]]},
"Persian":{"family":"Indo-European › Indo-Iranian › Iranian › Western Iranian","about":"Descends from the Old Persian of the Achaemenid kings via Middle Persian. After the Arab conquest it took in thousands of Arabic words but kept its own grammar, and poets like Ferdowsi championed it. Perso-Arabic script. Fun fact: English 'paradise', 'bazaar' and 'pajamas' all come from Persian."},
"Icelandic":{"family":"Indo-European › Germanic › North Germanic","about":"Descends from the Old Norse of Viking settlers who reached Iceland around 874. Isolation and deliberate purism kept it close to its ancestor, and new words are built from native roots, like 'tölva' (computer, 'number prophetess'). Latin script with þ and ð. Fun fact: Icelanders can still read medieval sagas."},
"Italian":{"family":"Indo-European › Italic › Romance","about":"Grew from Vulgar Latin; the standard is based on 14th-century Florentine, the language of Dante, Petrarch and Boccaccio. Germanic Lombards, Arabs in Sicily, and French and Spanish rulers all left words. Latin script. Fun fact: only a small minority of Italians spoke standard Italian at unification in 1861."},
"Jamaican Patois":{"family":"English-based creole","about":"Formed in the 17th and 18th centuries on Jamaica's plantations, where enslaved West Africans, many of them Akan speakers, reshaped English. Most words are English, with West African words like 'nyam' (eat) and 'duppy' (ghost), plus some Spanish and Portuguese. Latin script, spelled informally. Fun fact: reggae carried it worldwide."},
"Japanese":{"family":"Japonic","about":"A Japonic language, probably brought to Japan by Yayoi-era migrants from the mainland. Chinese gave it writing and about half its vocabulary, and modern English adds many loanwords. Written in kanji plus the hiragana and katakana syllabaries. Fun fact: 'pan' (bread) came from Portuguese traders in the 1500s.","mix":[["Chinese (kango)",50],["Native (wago)",35],["Western loans (gairaigo)",10],["Hybrid",5]]},
"Swahili":{"family":"Niger-Congo › Atlantic-Congo › Bantu","about":"A Bantu language of the East African coast, shaped by centuries of Indian Ocean trade. Arabic supplied many words, including its name from 'sawāḥil' (coasts), and Persian, Portuguese, Hindi, German and English added more. Once in Arabic script, now Latin. Fun fact: English 'safari' comes from Swahili for journey."},
"Kyrgyz":{"family":"Turkic › Kipchak","about":"A Kipchak Turkic language of the nomads of the Tian Shan mountains, close to Kazakh. Persian and Arabic came via Islam and Silk Road trade, then Russian during Soviet rule. Written in Cyrillic since 1940. Fun fact: the Epic of Manas, one of the longest poems in the world, is in Kyrgyz."},
"Khmer":{"family":"Austroasiatic › Khmeric","about":"An Austroasiatic language written since the 7th century, among the oldest recorded in Southeast Asia. Sanskrit and Pali came with Hinduism and Buddhism, and French during colonial rule. Written in Khmer script, derived from South Indian Pallava. Fun fact: unlike Thai and Lao it is not tonal, and Thai borrowed many Khmer words."},
"Gilbertese":{"family":"Austronesian › Oceanic › Micronesian","about":"Kiribati's language, a Micronesian branch of Oceanic. Missionaries wrote it down in the 1800s with just 13 letters, and English words arrived with whalers and colonial rule. Latin script. Fun fact: 'ti' is pronounced 's', so Kiribati is said 'Kiribas', the local way of saying 'Gilberts'."},
"Korean":{"family":"Koreanic","about":"A Koreanic language with no proven relatives, largely descended from the speech of the Silla kingdom. Chinese supplied over half its vocabulary, plus some Japanese and much modern English. Written in Hangul, created in 1443 under King Sejong. Fun fact: Hangul's consonant shapes picture the mouth and tongue making each sound.","mix":[["Chinese (Sino-Korean)",60],["Native",30],["Western loans",5],["Hybrid",5]]},
"Kazakh":{"family":"Turkic › Kipchak","about":"A Kipchak Turkic language of the steppe nomads who formed the Kazakh Khanate in the 15th century. Arabic and Persian came with Islam, and Russian during Tsarist and Soviet rule. Written in Cyrillic, now switching to a Latin alphabet. Fun fact: it has a living tradition of 'aitys', improvised sung poetry duels."},
"Lao":{"family":"Kra-Dai › Tai › Southwestern Tai","about":"A Tai language brought south from southern China by Tai migrants, close enough to Thai that speakers understand each other. Pali and Sanskrit came with Theravada Buddhism, plus Khmer and French loans. Written in Lao script, descended from Old Khmer. Fun fact: the Vientiane dialect has six tones."},
"Sinhala":{"family":"Indo-European › Indo-Iranian › Indo-Aryan › Insular","about":"An Indo-Aryan language brought to Sri Lanka from northern India around the 5th century BC, then isolated from its relatives. Pali came with Buddhism, Tamil neighbours added much, then Portuguese, Dutch and English. Written in the rounded Sinhala script, of Brahmi origin. Fun fact: 'Sinhala' is linked to 'sinha', lion."},
"Sesotho":{"family":"Niger-Congo › Bantu › Sotho-Tswana","about":"A Bantu language of Lesotho and South Africa, in the Sotho-Tswana group. Nguni neighbours like Zulu lent it click sounds, and Afrikaans and English added loans. French missionaries first wrote it down in the 1830s in Latin script. Fun fact: King Moshoeshoe I united the Basotho nation in the early 1800s."},
"Lithuanian":{"family":"Indo-European › Balto-Slavic › Baltic","about":"An East Baltic language famous among linguists for keeping many ancient Indo-European features. Polish, Belarusian and German contact added loans. Latin script; when Russia banned it from 1864 to 1904, book smugglers kept it alive. Fun fact: some words echo Sanskrit, like 'sūnus' and 'sūnú' (son)."},
"Luxembourgish":{"family":"Indo-European › Germanic › West Germanic › Moselle Franconian","about":"A Moselle Franconian dialect of German that grew into a national language, made official in 1984. Centuries between France and Germany gave it many French words, like 'merci' and 'Trottoir' (pavement). Latin script. Fun fact: Luxembourgers greet each other with 'Moien'."},
"Latvian":{"family":"Indo-European › Balto-Slavic › Baltic","about":"An East Baltic language, cousin of Lithuanian, which absorbed traces of Finnic Livonian. German crusaders and merchants, then Swedish and Russian rule, added loans. Latin script with macrons. Fun fact: Latvians have collected over a million short folk songs called 'dainas'."},
"Moroccan Arabic":{"family":"Afro-Asiatic › Semitic › Arabic › Maghrebi","about":"Darija grew from Arabic brought by conquerors from the 7th century and later by Bedouin tribes, blended with Berber (Amazigh) languages. French and Spanish add many words. Usually written in Arabic script, but online often in Latin letters. Fun fact: texters use '3' for ع and '7' for ح."},
"Romanian":{"family":"Indo-European › Italic › Romance › Eastern Romance","about":"Descends from the Latin of Roman Dacia, conquered in 106 AD. Cut off from other Romance languages, it absorbed Slavic, Hungarian, Greek and Turkish words, then many French ones. Latin script, though Cyrillic was used until the 1860s. Fun fact: it still has Latin-style noun cases."},
"Montenegrin":{"family":"Indo-European › Slavic › South Slavic","about":"A standard form of the South Slavic language it shares with Serbian, Croatian and Bosnian, descended from Common Slavic. Ottoman rule left Turkish words and Venice left Italian ones on the coast. Written in Latin and Cyrillic. Fun fact: its 2009 standard added two letters, ś and ź."},
"Malagasy":{"family":"Austronesian › Malayo-Polynesian › Barito","about":"Its ancestors sailed from Borneo across the Indian Ocean to Madagascar over 1,000 years ago, and its closest relative is Ma'anyan. Bantu, Arabic, French and English left loans. Latin script, earlier the Arabic-based Sorabe. Fun fact: it is the westernmost Austronesian language."},
"Marshallese":{"family":"Austronesian › Oceanic › Micronesian","about":"A Micronesian language of the Marshall Islands, descended from the speech of Oceanic seafarers. German, Japanese and American administrations left loanwords. Latin script with letters like ļ, m̧ and n̄. Fun fact: Marshallese navigators used stick charts to map ocean swells."},
"Macedonian":{"family":"Indo-European › Slavic › South Slavic","about":"A South Slavic language close to Bulgarian; Old Church Slavonic was based on a dialect from its region. Ottoman rule added Turkish words, plus Greek. Codified in 1945 in Cyrillic with letters like ѓ, ќ and ѕ. Fun fact: it has three definite articles, depending on how near or far something is."},
"Bambara":{"family":"Niger-Congo › Mande › Manding","about":"A Manding language of Mali and its main lingua franca, close to Dyula and Malinke. The Mali Empire spread Manding speech; Arabic came with Islam and French with colonial rule. Latin script, also N'Ko and Arabic Ajami. Fun fact: griots still recite the epic of Sundiata in Manding."},
"Burmese":{"family":"Sino-Tibetan › Tibeto-Burman › Lolo-Burmese","about":"Brought south into the Irrawaddy valley by the Bamar by the 9th century. Pali came with Theravada Buddhism, plus Mon and English loans. Written in the rounded Burmese script, from Mon. Fun fact: the letters are round because they were written on palm leaves, which straight lines would tear."},
"Mongolian":{"family":"Mongolic › Central Mongolic","about":"Descends from Middle Mongol, the language of Genghis Khan's empire. Tibetan Buddhism added Tibetan and Sanskrit words, plus Chinese and Russian ones. Mongolia uses Cyrillic since the 1940s while reviving the traditional script. Fun fact: that traditional script is written in vertical columns, top to bottom."},
"Hassaniya Arabic":{"family":"Afro-Asiatic › Semitic › Arabic › Maghrebi","about":"Brought to the western Sahara from the 1400s by the Beni Hassan Bedouin Arab tribes, who mixed with Berber (Zenaga) speakers and gradually replaced their language. Spoken in Mauritania and Western Sahara. Written, when at all, in Arabic script. Fun fact: it keeps classical Arabic sounds lost in other Maghrebi dialects and carries rich oral poetry."},
"Maltese":{"family":"Afro-Asiatic › Semitic › Arabic","about":"Descends from the Siculo-Arabic spoken when Arabs ruled Malta (870 to 1091), then centuries under Sicilian, Italian, Knights of St John and British rule layered on Romance and English words. Fun fact: it is the only Semitic language that is official in the EU and the only one written in the Latin alphabet, with letters like ħ and ż.","mix":[["Arabic (Siculo-Arabic)",35],["Sicilian & Italian",50],["English",5],["Other",10]]},
"Mauritian Creole":{"family":"French-based creole","about":"Born in the 1700s on French sugar plantations, where enslaved people from Madagascar, East and West Africa built a new language from French. Later Indian, Chinese and English contact added words. Written in the Latin alphabet with a standard spelling since 2011. Fun fact: it is the everyday language of almost every Mauritian, whatever their roots.","mix":[["French",90],["Other (Malagasy, Bhojpuri, English, etc.)",10]]},
"Dhivehi":{"family":"Indo-European › Indo-Aryan › Insular Indo-Aryan","about":"Settlers from Sri Lanka and South India brought an early form of Sinhala to the Maldives over 1,500 years ago. Isolation, Islam (from 1153), Arabic, Persian, Tamil and English shaped it since. Written in Thaana, right to left. Fun fact: Thaana's first nine letters come from Arabic numerals and the next nine from Dhivehi numerals."},
"Chichewa":{"family":"Niger-Congo › Bantu › Nyanja-Sena","about":"A Bantu language whose ancestors arrived with the Bantu migrations; the Chewa people of the Maravi kingdom spread it across Malawi, Zambia and Mozambique. English and some Swahili loans came with trade and colonial rule. Written in the Latin alphabet. Fun fact: Malawi's name likely comes from Maravi, meaning flames or rays of light."},
"Afrikaans":{"family":"Indo-European › Germanic › West Germanic › Low Franconian","about":"Grew from the 17th-century Dutch of settlers at the Cape, reshaped by enslaved people speaking Malay and Portuguese creole, and by Khoekhoe neighbours. Written in the Latin alphabet. Fun fact: the earliest Afrikaans texts were written in Arabic script by Cape Malay Muslims, and it became an official language only in 1925.","mix":[["Dutch",90],["Malay, Portuguese, Khoekhoe & other",10]]},
"Hausa":{"family":"Afro-Asiatic › Chadic › West Chadic","about":"A Chadic cousin of Arabic and Hebrew, spread by the Hausa city states and their long-distance traders across West Africa. Islam brought many Arabic words; English and French came later. Written in Latin (Boko) and older Arabic-based Ajami. Fun fact: with tens of millions of second-language speakers, it is one of Africa's great trade languages."},
"Nigerian Pidgin":{"family":"English-based creole","about":"Grew from contact between Africans and English traders on the coast from the 1600s, then spread through colonial towns, markets and music. Grammar and many words come from Yoruba, Igbo and Portuguese. Written in the Latin alphabet. Fun fact: well over 100 million people use it, and 'sabi' (to know) comes from Portuguese 'saber'."},
"Norwegian":{"family":"Indo-European › Germanic › North Germanic","about":"Descends from Old Norse, the language of the Vikings. Centuries of union with Denmark brought heavy Danish influence, and Hanseatic traders added Low German words. Written in the Latin alphabet with æ, ø and å. Fun fact: it has two official written standards, Bokmål and Nynorsk, and no official spoken standard."},
"Nepali":{"family":"Indo-European › Indo-Aryan › Northern (Pahari)","about":"Grew from Khas, spoken in the western Himalaya, and spread as the Gorkha kingdom unified Nepal in the 1700s. Sanskrit gave learned words; Hindi, Persian and English added more. Written in Devanagari. Fun fact: it was long called Gorkhali or Khas-kura, and the name Nepali only took hold in the 20th century."},
"Nauruan":{"family":"Austronesian › Oceanic › Micronesian","about":"A Micronesian language that developed on tiny Nauru, with words borrowed from German (colonial rule), English, Kiribati and Pacific neighbours. Written in the Latin alphabet. Fun fact: Nauru is the world's third smallest country, so Nauruan has only about 10,000 speakers and is one of the least studied Pacific languages."},
"Māori":{"family":"Austronesian › Oceanic › Polynesian › Eastern Polynesian","about":"Polynesian voyagers brought it to Aotearoa around 1300 from East Polynesia; it is close to Tahitian and Cook Islands Māori. Missionaries wrote it down in the Latin alphabet in the 1800s, adding English loans like 'pukapuka' (book). Fun fact: language nests called kōhanga reo helped revive it from the 1980s."},
"Tok Pisin":{"family":"English-based creole","about":"Grew from Pacific plantation pidgin in the 1800s, when Melanesian workers met English speakers; German colonial rule and the Tolai language of New Britain shaped it. Written in the Latin alphabet. Fun fact: 'pikinini' (child) comes from Portuguese, and it is now the most widely spoken language in Papua New Guinea."},
"Filipino":{"family":"Austronesian › Malayo-Polynesian › Philippine › Central Philippine","about":"The national standard based on Tagalog of Manila. Over 300 years of Spanish rule added thousands of words, plus Malay, Chinese, Sanskrit and English loans. Once written in Baybayin, now in the Latin alphabet. Fun fact: 'kumusta' (how are you) comes from Spanish '¿cómo está?'."},
"Urdu":{"family":"Indo-European › Indo-Aryan › Central","about":"Grew in north India from the 1200s as local Hindustani mixed with Persian, Arabic and Turkic of the Delhi Sultanate and Mughal courts. Written in Nastaliq Perso-Arabic script. Fun fact: its name comes from Turkic 'ordu', army camp, the same root as English 'horde', and spoken Urdu is nearly identical to Hindi."},
"Polish":{"family":"Indo-European › Balto-Slavic › Slavic › West Slavic","about":"Descends from Proto-Slavic, shaped by Latin through the Church, plus German, Czech, French and Italian words. Written in the Latin alphabet with letters like ą, ę, ł and ż. Fun fact: the tongue twister 'W Szczebrzeszynie chrząszcz brzmi w trzcinie' (a beetle buzzes in the reeds) is a classic test for learners."},
"Palauan":{"family":"Austronesian › Malayo-Polynesian","about":"A Malayo-Polynesian language with no close relatives, spoken in Palau. Spanish, German, Japanese and American rule each left words behind. Written in the Latin alphabet. Fun fact: from the Japanese era, Palauans still say 'daijobu' for okay and 'senkyo' for election."},
"Serbian":{"family":"Indo-European › Balto-Slavic › Slavic › South Slavic","about":"Descends from Proto-Slavic brought to the Balkans in the 500s and 600s. Church Slavonic, Greek and centuries of Ottoman rule added many Turkish words. Fun fact: it is written in both Cyrillic and Latin, and reformer Vuk Karadžić gave it the rule 'write as you speak', one letter per sound."},
"Russian":{"family":"Indo-European › Balto-Slavic › Slavic › East Slavic","about":"Grew from Old East Slavic of Kyivan Rus'. Church Slavonic gave learned words; Tatar, Dutch, German, French and English added more. Written in Cyrillic, derived from Greek. Fun fact: 'vokzal' (railway station) is said to come from Vauxhall, a London pleasure garden with a famous station."},
"Kinyarwanda":{"family":"Niger-Congo › Bantu › Rwanda-Rundi","about":"A Bantu language that spread with the Rwandan kingdom, mutually intelligible with Kirundi of Burundi. French, English and Swahili loans arrived in colonial and modern times. Written in the Latin alphabet. Fun fact: almost every Rwandan speaks it, making it one of Africa's few truly national languages."},
"Solomon Islands Pijin":{"family":"English-based creole","about":"Grew from Melanesian Pidgin used by islanders working on plantations in Queensland, Fiji and Samoa in the late 1800s, then on local plantations. A sister of Tok Pisin and Bislama. Written in the Latin alphabet. Fun fact: in a country with over 70 languages, Pijin is the common tongue that lets everyone talk."},
"Seychellois Creole":{"family":"French-based creole","about":"Born on 18th-century French plantations among enslaved people from Africa and Madagascar, sharing roots with Mauritian Creole. English came under British rule. Written in the Latin alphabet. Fun fact: Kreol Seselwa became an official language in 1981, and Creole Day festival is held every October.","mix":[["French",90],["Other (Malagasy, English, etc.)",10]]},
"Swedish":{"family":"Indo-European › Germanic › North Germanic","about":"Descends from Old Norse. Hanseatic traders brought masses of Low German words, later French and English. Written in the Latin alphabet with å, ä and ö. Fun fact: it has pitch accent, so 'anden' can mean 'the duck' or 'the spirit' depending on the melody."},
"Slovenian":{"family":"Indo-European › Balto-Slavic › Slavic › South Slavic","about":"Descends from Slavic brought to the eastern Alps in the 500s. Centuries under Habsburg rule added German words. Written in the Latin alphabet with č, š and ž. Fun fact: it still uses the dual, a grammar form for exactly two things, and the Freising manuscripts from around 1000 AD are its earliest texts."},
"Slovak":{"family":"Indo-European › Balto-Slavic › Slavic › West Slavic","about":"Descends from Proto-Slavic, very close to Czech, with influence from Latin, German and Hungarian. Standardized by Ľudovít Štúr in the 1840s. Written in the Latin alphabet. Fun fact: syllables can be built around r or l, so words like 'vlk' (wolf) and 'krk' (neck) have no vowels at all."},
"Krio":{"family":"English-based creole","about":"Formed in Freetown from the 1790s by freed Black settlers from Nova Scotia, Jamaican Maroons and Liberated Africans, many of them Yoruba. English is the base, with Yoruba, Portuguese and other African words. Written in the Latin alphabet. Fun fact: 'Kushɛ', a common greeting, comes from Yoruba."},
"Somali":{"family":"Afro-Asiatic › Cushitic › East Cushitic","about":"A Cushitic language of the Horn of Africa. Islam and Indian Ocean trade brought many Arabic words, plus Italian and English from colonial times. Written in the Latin alphabet since 1972. Fun fact: in its spelling 'x' stands for a breathy h and 'c' for an Arabic-style ʿayn, as in 'Xamar' (Mogadishu)."},
"Juba Arabic":{"family":"Arabic-based creole","about":"Grew in the 1800s around Turco-Egyptian army camps in southern Sudan, where soldiers and locals from many groups built a simple Arabic pidgin. Bari and other local languages and English shaped it. Written in Latin or Arabic script. Fun fact: though English is official, Juba Arabic is the street language of South Sudan's capital."},
"Swazi":{"family":"Niger-Congo › Bantu › Southern Bantu › Nguni","about":"SiSwati is a Nguni language close to Zulu, carried south with Bantu migrations; the Swazi kingdom made it its own. Click sounds came from Khoisan neighbours. Written in the Latin alphabet. Fun fact: it is the national language of Eswatini, one of the world's last absolute monarchies."},
"Chadian Arabic":{"family":"Afro-Asiatic › Semitic › Arabic › Sudanic","about":"Brought by Bedouin Arab herders who moved west from Sudan from the 1300s, mixing with local languages like Kanuri and Sara. Written in Arabic or Latin script. Fun fact: also called Shuwa Arabic, it is the main lingua franca of Chad and is spoken as far as northern Cameroon and Nigeria."},
"Thai":{"family":"Kra-Dai › Tai › Southwestern Tai","about":"Tai peoples moved south from southern China into Southeast Asia around 1,000 years ago. Pali and Sanskrit (via Buddhism) and Khmer gave many words, later Chinese and English. Its script grew from Old Khmer. Fun fact: it has five tones, and Bangkok's full ceremonial name is among the world's longest place names."},
"Tajik":{"family":"Indo-European › Indo-Iranian › Iranian › Persian","about":"A form of Persian, descended from the Persian spread across Central Asia after the Arab conquest. Uzbek and Russian added words. Written in Cyrillic since 1940. Fun fact: Tajiks claim Rudaki, the father of Persian poetry, and can read classical Persian poets once transliterated."},
"Tetum":{"family":"Austronesian › Malayo-Polynesian › Central-Eastern","about":"An Austronesian language of Timor that became a trade tongue. Over 400 years of Portuguese rule added many words, plus Malay and Indonesian. Written in the Latin alphabet. Fun fact: Tetun Prasa, the Dili variety, is co-official with Portuguese, and 'obrigadu' is how you say thank you."},
"Turkmen":{"family":"Turkic › Oghuz","about":"An Oghuz Turkic language, close to Turkish and Azerbaijani, carried by Turkic tribes to Central Asia. Persian, Arabic and Russian added words. Written in Latin since 1993, after Arabic and Cyrillic. Fun fact: it keeps long vowels that most Turkic languages lost."},
"Tunisian Arabic":{"family":"Afro-Asiatic › Semitic › Arabic › Maghrebi","about":"Arabic arrived with the 7th-century conquests and blended with Berber and Latin-era speech. Andalusian refugees, Ottomans, Italians and the French all added words. Usually written in Arabic or Latin script. Fun fact: Tunisians say 'aslema' for hello and 'barcha' (a lot), and Italian gave 'fattura' (bill)."},
"Tongan":{"family":"Austronesian › Oceanic › Polynesian › Tongic","about":"A Polynesian language carried by Lapita voyagers about 3,000 years ago. Missionaries wrote it in the Latin alphabet in the 1800s, adding English words. Fun fact: it has special respectful vocabulary for the king and nobles, and Tonga was never colonized."},
"Turkish":{"family":"Turkic › Oghuz","about":"Oghuz Turks brought it to Anatolia in the 1000s. Ottoman Turkish absorbed huge numbers of Arabic and Persian words. In 1928 Atatürk replaced Arabic script with the Latin alphabet, and a reform swapped many loans for Turkic words. Fun fact: thanks to agglutination, one word can be a whole sentence."},
"Tuvaluan":{"family":"Austronesian › Oceanic › Polynesian › Ellicean","about":"A Polynesian language, close to Samoan and Tokelauan, spoken on Tuvalu's nine atolls. Samoan missionaries in the 1800s spread Samoan Bible words, and English came later. Written in the Latin alphabet. Fun fact: Tuvalu earns a good share of its income from leasing its '.tv' internet domain."},
"Ukrainian":{"family":"Indo-European › Balto-Slavic › Slavic › East Slavic","about":"Grew from Old East Slavic of Kyivan Rus'. Long ties with Poland and Lithuania brought many Polish words, plus Church Slavonic and Turkic loans. Written in Cyrillic with letters ї, є and ґ. Fun fact: Taras Shevchenko's 19th-century poetry made it a literary language."},
"Luganda":{"family":"Niger-Congo › Bantu › Nyoro-Ganda","about":"The language of the Buganda kingdom on Lake Victoria, a Bantu language. Swahili, Arabic and English loans came with trade and colonial rule. Written in the Latin alphabet. Fun fact: Uganda's name comes from 'Buganda', and it is the most spoken language in Kampala."},
"Uzbek":{"family":"Turkic › Karluk","about":"Descends from Chagatai, the Turkic literary language of Timurid Central Asia. Heavy Persian (Tajik) influence plus Arabic and Russian words. Written in Latin since 1993, though Cyrillic is still common. Fun fact: its closest living relative is Uyghur, and Persian contact cost it Turkic vowel harmony."},
"Vietnamese":{"family":"Austroasiatic › Vietic","about":"A Vietic language related to Khmer. A thousand years of Chinese rule gave it a vast Sino-Vietnamese vocabulary; French added words like 'cà phê'. Once written in Chinese-based chữ Nôm, now in Latin chữ Quốc ngữ, developed by Portuguese and French missionaries. Fun fact: it has six tones in the north.","mix":[["Chinese (Sino-Vietnamese)",60],["Native Vietic",35],["French & other",5]]},
"Bislama":{"family":"English-based creole","about":"Grew in the 1800s from pidgin used in the sea cucumber (bêche-de-mer) trade and on plantations in Queensland and Fiji. French added words under joint British-French rule. Written in the Latin alphabet. Fun fact: its name comes from bêche-de-mer, and it is the national language of Vanuatu.","mix":[["English",95],["French & other",5]]},
"Samoan":{"family":"Austronesian › Oceanic › Polynesian › Samoic","about":"A Polynesian language brought by early voyagers about 3,000 years ago. Missionaries wrote it in the Latin alphabet in the 1830s. Fun fact: Samoan has a respectful register for chiefs, and English 'tattoo' comes from Polynesian 'tatau'."},
"Zulu":{"family":"Niger-Congo › Bantu › Southern Bantu › Nguni","about":"A Nguni Bantu language that grew with the Zulu kingdom under Shaka in the 1800s. Clicks were borrowed from Khoisan neighbours; English and Afrikaans added words. Written in the Latin alphabet. Fun fact: it is South Africa's most spoken home language, and the letters c, q and x mark three click sounds."},
"Bemba":{"family":"Niger-Congo › Bantu › Sabi","about":"A Bantu language from the Bemba kingdom of northern Zambia. Mining on the Copperbelt spread it as a lingua franca, with English loans. Written in the Latin alphabet. Fun fact: it is the most widely spoken language in Zambia, and 'mwapoleni' is a common greeting."},
"Shona":{"family":"Niger-Congo › Bantu › Shona","about":"A Bantu language whose ancestors built Great Zimbabwe. English loans came with colonial rule. Written in the Latin alphabet. Fun fact: Zimbabwe gets its name from Shona 'dzimba dza mabwe', houses of stone."},
"Friulian":{"family":"Indo-European › Italic › Romance › Rhaeto-Romance","about":"Grew from Latin spoken around Roman Aquileia, over a Celtic substrate, with German, Slovene and Venetian influence. Written in the Latin alphabet. Fun fact: it is a cousin of Romansh, and filmmaker Pier Paolo Pasolini wrote poetry in it."},
"New York English":{"family":"Indo-European › Germanic › West Germanic › English","about":"An American English accent shaped by Dutch settlers, Irish, Italian, Jewish and Puerto Rican immigrants. Written in the Latin alphabet. Fun fact: 'stoop' and 'cookie' come from Dutch, 'schlep' from Yiddish, and the classic accent drops its r's as in 'cawfee'."},
"Rajasthani":{"family":"Indo-European › Indo-Aryan › Western","about":"A group of Indo-Aryan languages like Marwari, grew from Apabhramsha alongside Gujarati. Sanskrit, Persian and Hindi added words. Written in Devanagari, historically also Mahajani. Fun fact: its bardic Dingal poetry was used to sing the deeds of Rajput warriors."},
"Punjabi":{"family":"Indo-European › Indo-Aryan › Northwestern","about":"Grew from Shauraseni Prakrit in the land of five rivers. Persian and Arabic came with Muslim rulers, later English. Written in Gurmukhi in India and Shahmukhi in Pakistan. Fun fact: it is a rare tonal Indo-European language, and Guru Nanak's hymns made it sacred to Sikhs."},
"Mexican Spanish (what's up?)":{"family":"Indo-European › Italic › Romance › Ibero-Romance","about":"Spanish brought by conquistadors in 1519 met Nahuatl, Maya and other indigenous languages. Written in the Latin alphabet. Fun fact: 'chocolate', 'tomate' and 'aguacate' come from Nahuatl, and Mexicans greet friends with '¿Qué onda?', meaning what's up."},
"Egyptian Arabic":{"family":"Afro-Asiatic › Semitic › Arabic › Egyptian","about":"Arabic came with the 7th-century conquest and replaced Coptic, which left a substrate. Turkish, Italian, French and English added words. Written in Arabic script. Fun fact: Cairo's film and TV industry made it the most widely understood Arabic dialect."},
"Moroccan Arabic (all good?)":{"family":"Afro-Asiatic › Semitic › Arabic › Maghrebi","about":"Darija formed as Arabic arrived from the 7th century and mixed with Amazigh (Berber) languages. Andalusian refugees, Spanish and French added words. Written in Arabic or Latin script. Fun fact: Moroccans check in with 'Kulshi mezyan?', meaning all good, and answer 'Bikhir'."},
"Mandarin":{"family":"Sino-Tibetan › Sinitic › Mandarin","about":"Grew from northern Chinese spoken around imperial capitals; standard Mandarin is based on Beijing speech. Written in Chinese characters, simplified on the mainland, with pinyin for sounds. Fun fact: it has four tones, and more people speak it as a first language than any other language."},
"Tamil, one of four official languages with English, Malay and Mandarin":{"family":"Dravidian › Southern Dravidian","about":"One of the world's oldest living languages, with Sangam poetry over 2,000 years old. Sanskrit, Prakrit and later English and Portuguese added words. Its script grew from Brahmi. Fun fact: English 'catamaran' comes from Tamil 'kattumaram', and in Singapore it is official alongside English, Malay and Mandarin."},
"isiXhosa":{"family":"Niger-Congo › Bantu › Southern Bantu › Nguni","about":"A Nguni Bantu language whose speakers settled the Eastern Cape. Long contact with Khoekhoe people gave it many clicks; English and Afrikaans added words. Written in the Latin alphabet. Fun fact: it was Nelson Mandela's mother tongue, and the 'X' in Xhosa is itself a click."},
"Yorùbá":{"family":"Niger-Congo › Volta-Niger › Yoruboid","about":"Grew in southwest Nigeria and Benin, language of Ife and Oyo kingdoms. Arabic came with Islam, English with colonialism. Written in Latin with tone marks, pioneered by Bishop Samuel Ajayi Crowther. Fun fact: it has three tones, and lives on in Brazil and Cuba through Candomblé and Santería."},
"Quechua, the Incas' language":{"family":"Quechuan","about":"A family of languages from the central Andes, older than the Incas, who made it the language of their empire. Spanish added many words after 1532. Written in the Latin alphabet. Fun fact: English 'llama', 'puma', 'condor' and 'jerky' (from 'ch'arki') all come from Quechua."},
"Argentine Spanish":{"family":"Indo-European › Italic › Romance › Ibero-Romance","about":"Rioplatense Spanish took shape as Spanish settlers met millions of Italian immigrants in the 1800s and 1900s, which gave it a sing-song melody and lunfardo slang. Written in the Latin alphabet. Fun fact: Argentines say 'vos' instead of 'tú', pronounce 'll' and 'y' as 'sh', and use 'che' to call friends."},
"Australian English":{"family":"Indo-European › Germanic › West Germanic › English","about":"Grew from the mixed British and Irish speech of convicts and settlers from 1788. Aboriginal languages added words. Written in the Latin alphabet. Fun fact: 'kangaroo' comes from Guugu Yimithirr 'gangurru', and Australians shorten everything, so afternoon becomes 'arvo'."},
"London English":{"family":"Indo-European › Germanic › West Germanic › English","about":"From Cockney to Multicultural London English, London speech has absorbed influences from Jamaican, West African, Bangladeshi and other communities. Written in the Latin alphabet. Fun fact: Cockney rhyming slang gives 'apples and pears' for stairs, and young Londoners say 'innit' and 'bare'."},
"Balinese":{"family":"Austronesian › Malayo-Polynesian › Malayo-Sumbawan › Bali-Sasak","about":"Austronesian language of Bali, deeply shaped by Old Javanese, Sanskrit through Hinduism, and Indonesian. Written in Latin and the Balinese script from Brahmi. Fun fact: it has speech levels, so you use different words depending on the caste of who you are addressing."},
"Newari":{"family":"Sino-Tibetan › Tibeto-Burman › Newaric","about":"Nepal Bhasa is the Tibeto-Burman language of the Newars of the Kathmandu Valley, with a huge stock of Sanskrit and Pali loans from Hindu and Buddhist learning. Written in Ranjana and Prachalit script, now often Devanagari. Fun fact: its oldest document dates to 1114, and the Newars built the valley's famous temples."},
"Sinhala (may you live long)":{"family":"Indo-European › Indo-Aryan › Insular Indo-Aryan","about":"Brought to Sri Lanka by settlers from northern India around 500 BC. Pali, Sanskrit, Tamil, Portuguese, Dutch and English all added words. Written in its own round script. Fun fact: the greeting 'āyubōvan' means may you live long, and the letters are round because straight lines would split palm-leaf manuscripts."},
"Québécois French":{"family":"Indo-European › Italic › Romance › Gallo-Romance","about":"Grew from the French of 17th-century settlers from Normandy, Paris and western France, isolated from France after 1763 and surrounded by English. Written in the Latin alphabet. Fun fact: its strongest swear words are church terms, like 'tabarnak' (tabernacle), and it still keeps old words like 'char' for car."},
"Thai (add 'ka' or 'krap' to be polite)":{"family":"Kra-Dai › Tai › Southwestern Tai","about":"Tai peoples moved south from southern China around 1,000 years ago. Pali, Sanskrit and Khmer gave many words, later Chinese and English. Its script grew from Old Khmer. Fun fact: politeness lives in particles: men end sentences with 'khrap' and women with 'kha', as in 'sawasdee khrap'."},
"Colombian Spanish (what's up?)":{"family":"Indo-European › Italic › Romance › Ibero-Romance","about":"Spanish arrived in the 1500s and mixed with indigenous languages like Muisca, African languages on the Caribbean coast, and later English. Written in the Latin alphabet. Fun fact: Colombians ask '¿Qué más?' or '¿Quiubo?' for what's up, call friends 'parce', and many use the formal 'usted' even with family."}};
